int main(int argc,char** argv){QApplication::setAttribute(Qt::AA_DontUseNativeDialogs);QApplication app(argc,argv);const std::map<std::string,void(*)()> cases{{"subject_nonmodal",subject_nonmodal},{"subject_canvas_preview",subject_canvas_preview},{"subject_preview_toggle",subject_preview_toggle},{"subject_cancel",subject_cancel},{"subject_apply",subject_apply},{"subject_ranges",subject_ranges},{"subject_shift_step",subject_shift_step},{"gradient_picker_app",gradient_picker_app},{"gradient_working_cancel",gradient_working_cancel},{"gradient_working_apply",gradient_working_apply},{"gradient_parent_cancel",gradient_parent_cancel},{"gradient_parent_apply",gradient_parent_apply},{"gradient_canvas_sample",gradient_canvas_sample},{"gradient_endpoint_exclusion",gradient_endpoint_exclusion}};try{require(argc==2&&cases.contains(argv[1]),"provide named panel follow-up case");cases.at(argv[1])();std::printf("PASS %s\n",argv[1]);return 0;}catch(const std::exception& error){std::fprintf(stderr,"FAIL %s: %s\n",argc>1?argv[1]:"argument",error.what());return 1;}}
